const input = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const correlationId = String(input.correlation_id ?? `noavia-${Date.now()}-${Math.random().toString(16).slice(2)}`);
const errors = [];
const required = (value, field) => { if (typeof value !== 'string' || !value.trim()) { errors.push({ field, message: `${field} is required` }); return ''; } return value.trim(); };
const subject = required(input.subject, 'subject');
const body = required(input.body ?? input.message ?? input.text, 'body');
const requesterEmail = required(input.requester_email ?? input.from ?? input.email, 'requester_email');
if (requesterEmail && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(requesterEmail)) errors.push({ field: 'requester_email', message: 'requester_email is invalid' });
const config = (input.config && typeof input.config === 'object') ? input.config : {};
const normalizedConfig = {};
for (const key of ['sheet_id', 'sheet_name', 'default_route_email', 'from_email']) normalizedConfig[key] = required(config[key], `config.${key}`);
const ragMinScore = Number(config.rag_min_score ?? 0.6);
if (!Number.isFinite(ragMinScore) || ragMinScore < 0 || ragMinScore > 1) errors.push({ field: 'config.rag_min_score', message: 'config.rag_min_score must be between 0 and 1' });
const attachment = $binary?.data;
if (attachment) { const mime = String(attachment.mimeType ?? '').toLowerCase(); const name = String(attachment.fileName ?? '').toLowerCase(); if (mime !== 'application/pdf' && !name.endsWith('.pdf')) errors.push({ field: 'attachment', message: 'attachment must be a PDF' }); const size = Number(attachment.fileSize ?? 0); if (Number.isFinite(size) && size > 10 * 1024 * 1024) errors.push({ field: 'attachment', message: 'PDF exceeds 10 MB' }); }
if (errors.length) return [{ json: { ok: false, error: { code: 'VALIDATION_ERROR', message: 'Ticket validation failed', details: errors }, correlation_id: correlationId, audit_logs: [] } }];
return [{ json: { ok: true, ticket: { id: String(input.ticket_id ?? correlationId), subject, body, text: `${subject}\n\n${body}`, requester_email: requesterEmail, locale: String(input.locale ?? 'en'), received_at: new Date().toISOString(), attachment_name: attachment?.fileName ?? null }, context: typeof input.context === 'object' && input.context ? input.context : {}, config: { ...normalizedConfig, routing_emails: config.routing_emails ?? {}, top_k: Math.min(Math.max(Number(config.top_k ?? 5), 1), 50), rag_min_score: ragMinScore, rag_filter: config.rag_filter ?? undefined, rag_collection: config.rag_collection ?? undefined }, correlation_id: correlationId, audit_logs: [] }, binary: $binary }];

const record = { ts: new Date().toISOString(), module: 'noavia.ticket-pipeline', interface_id: 'workflow.noavia-ticket-pipeline.v1', version: '1', correlation_id: $json.correlation_id, level: 'info', message: 'Ticket ingested' };
console.log(JSON.stringify(record));
return [{ json: { ...$json, audit_logs: [...($json.audit_logs ?? []), record] }, binary: $binary }];

const record = { ts: new Date().toISOString(), module: 'noavia.ticket-pipeline', interface_id: 'workflow.noavia-ticket-pipeline.v1', version: '1', correlation_id: $json.correlation_id, level: 'warn', message: 'Ticket rejected by validation' };
console.log(JSON.stringify(record));
return [{ json: { ...$json, audit_logs: [...($json.audit_logs ?? []), record] } }];

const base = $('audit.ingestion.v1').item.json;
const extracted = String($json.text ?? $json.data ?? '').trim();
return [{ json: { ...base, ticket: { ...base.ticket, text: extracted ? `${base.ticket.text}

PDF attachment:
${extracted}` : base.ticket.text } } }];

const base = $('audit.ingestion.v1').item.json;
const classification = $json.data;
const confidence = Number(classification?.confidence ?? 0);
const lowConfidence = !Number.isFinite(confidence) || confidence < 0.6;
const normalizedClassification = lowConfidence ? { ...classification, category: 'manual_review', tags: [...new Set([...(classification?.tags ?? []), 'low_confidence'])] } : classification;
return [{ json: { ...base, classification: normalizedClassification, processing_status: lowConfidence ? 'needs-manual-review' : 'routed', processing_error: lowConfidence ? { code: 'LOW_CLASSIFICATION_CONFIDENCE', message: 'Classification confidence is below 0.6' } : null } }];

const base = $('Prepare RAG Lookup').item.json;
const threshold = Number(base.config.rag_min_score ?? 0.6);
const matches = Array.isArray($json.data?.matches) ? $json.data.matches : [];
const ragMatches = matches.filter((match) => Number(match.score) >= threshold);
const knowledgeSources = ragMatches.map((match) => ({ id: String(match.id ?? ''), score: Number(match.score), citation: String(match.metadata?.source ?? match.metadata?.citation ?? match.id ?? 'knowledge-base'), metadata: match.metadata ?? {} }));
return [{ json: { ...base, rag_matches: ragMatches, knowledge_sources: knowledgeSources, rag_below_threshold: !ragMatches.length, processing_status: base.processing_status ?? 'routed', processing_error: base.processing_error ?? null } }];

const base = $('Prepare RAG Lookup').item.json;
const processingError = $json.error ?? { code: 'UPSTREAM_ERROR', message: 'RAG lookup failed' };
const record = { ts: new Date().toISOString(), module: 'noavia.ticket-pipeline', interface_id: 'workflow.noavia-ticket-pipeline.v1', version: '1', correlation_id: base.correlation_id, level: 'warn', message: 'AI RAG fallback activated' };
console.log(JSON.stringify(record));
return [{ json: { ...base, rag_matches: [], knowledge_sources: [], rag_below_threshold: false, processing_status: base.processing_status === 'needs-manual-review' ? base.processing_status : 'routed_without_rag', processing_error: base.processing_error ?? processingError, audit_logs: [...(base.audit_logs ?? []), record] } }];

const base = $('audit.ingestion.v1').item.json;
const processingError = $json.error ?? { code: 'UPSTREAM_ERROR', message: 'Classification failed' };
const record = { ts: new Date().toISOString(), module: 'noavia.ticket-pipeline', interface_id: 'workflow.noavia-ticket-pipeline.v1', version: '1', correlation_id: base.correlation_id, level: 'warn', message: 'AI classification fallback activated' };
console.log(JSON.stringify(record));
return [{ json: { ...base, classification: { category: 'manual_review', confidence: 0, tags: ['classification_failed'] }, rag_matches: [], knowledge_sources: [], rag_below_threshold: false, processing_status: 'needs-manual-review', processing_error: processingError, audit_logs: [...(base.audit_logs ?? []), record] } }];

const threshold = Number($json.config?.rag_min_score ?? 0.6);
const candidates = Array.isArray($json.rag_matches) ? $json.rag_matches : [];
const matches = candidates.filter((match) => Number(match?.score) >= threshold).slice(0, 5);
const sources = Array.isArray($json.knowledge_sources) && $json.knowledge_sources.length
  ? $json.knowledge_sources.filter((source) => Number(source?.score) >= threshold).slice(0, 5)
  : matches.map((match) => ({ id: String(match.id ?? ''), score: Number(match.score), citation: String(match.metadata?.source ?? match.metadata?.citation ?? match.id ?? 'knowledge-base'), metadata: match.metadata ?? {} }));
const citationBlock = sources.map((source, index) => `[${index + 1}] ${source.citation} (score: ${Number(source.score).toFixed(3)})`).join('\n');
const groundedContext = matches.map((match) => String(match.content ?? '')).filter(Boolean).join('\n\n');
const noPolicy = $json.rag_below_threshold || !matches.length;
const draftReply = noPolicy ? 'No specific policy found — this response is based on general knowledge.' : `Grounded knowledge:\n${groundedContext}\n\nCitations:\n${citationBlock}`;
return [{ json: { ...$json, rag_matches: matches, rag_below_threshold: noPolicy, knowledge_sources: sources, grounded_draft_reply: { text: draftReply, citations: sources, knowledge_source_metadata: sources.map((source) => source.metadata) } } }];

const configuredRoutes = (() => { try { const value = JSON.parse(String($env.NOAVIA_NOTIFY_ROUTE_ALLOWLIST_JSON ?? '{}')); return value && typeof value === 'object' && !Array.isArray(value) ? value : {}; } catch { return {}; } })();
const configuredEmail = (key) => { const candidate = configuredRoutes[key]; return typeof candidate === 'string' && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(candidate) ? candidate.trim() : null; };
const category = String($json.classification.category ?? 'manual_review');
const confidence = Number($json.classification.confidence ?? 0);
const needsManualReview = !Number.isFinite(confidence) || confidence < 0.6;
const routeCategory = needsManualReview ? 'manual_review' : category;
const routeEmail = configuredEmail(routeCategory) ?? configuredEmail('default');
const queue = routeCategory === 'manual_review' ? 'manual_review' : routeCategory;
const status = needsManualReview ? 'needs-manual-review' : $json.processing_status;
const contextSummary = ($json.rag_matches ?? []).slice(0, 5).map((m, i) => `${i + 1}. [${Number(m.score).toFixed(3)}] ${m.content}`).join('

');
return [{ json: { ...$json, processing_status: status, route: { queue, email: routeEmail }, sheet_row: { received_at: $json.ticket.received_at, ticket_id: $json.ticket.id, correlation_id: $json.correlation_id, requester_email: $json.ticket.requester_email, subject: $json.ticket.subject, category, confidence: $json.classification.confidence, tags: ($json.classification.tags ?? []).join(','), route_queue: queue, route_email: routeEmail, status, attachment_name: $json.ticket.attachment_name ?? '', rag_match_count: ($json.rag_matches ?? []).length, rag_context: contextSummary, error_code: $json.processing_error?.code ?? '', error_message: $json.processing_error?.message ?? '' }, notification_text: `NOAVIA ticket ${$json.ticket.id}
Category: ${category} (${Math.round(confidence * 100)}%)
Queue: ${queue}
Requester: ${$json.ticket.requester_email}
Subject: ${$json.ticket.subject}
Correlation ID: ${$json.correlation_id}
Status: ${status}

Grounded draft reply:
${$json.grounded_draft_reply?.text ?? ''}

Relevant context:
${contextSummary || '(none)'}` } }];

const base = $('route.by-classification.v1').item.json;
const sheets = $('notify.google-sheets.v1').item.json;
const describe = (value, target) => { const error = value?.error; if (!error) return null; return { target, code: String(error.code ?? 'DELIVERY_ERROR'), message: String(error.message ?? error) }; };
const failures = [describe(sheets, 'google_sheets'), describe($json, 'routing_email')].filter(Boolean);
const records = failures.map((failure) => ({ ts: new Date().toISOString(), module: 'noavia.ticket-pipeline', interface_id: 'workflow.noavia-ticket-pipeline.v1', version: '1', correlation_id: base.correlation_id, level: 'error', message: `${failure.target} delivery failed` }));
for (const record of records) console.log(JSON.stringify(record));
const auditLogs = [...(base.audit_logs ?? []), ...records];
if (failures.length) return [{ json: { ok: false, error: { code: 'DELIVERY_ERROR', message: 'One or more ticket deliveries failed', details: failures }, correlation_id: base.correlation_id, audit_logs: auditLogs } }];
return [{ json: { ok: true, data: { ticket_id: base.ticket.id, status: base.processing_status, route_queue: base.route.queue }, correlation_id: base.correlation_id, audit_logs: auditLogs } }];
